class Solution {
public:
    vector<int> processQueries(vector<int>& queries, int m) {
        int n = (int)queries.size();
        int sz = m + n;
        vector<int> bit(sz + 1, 0);
        vector<int> pos(m + 1);

        for (int i = 1; i <= m; i++) {
            pos[i] = n + i;
            for (int j = n + i; j <= sz; j += j & (-j))
                bit[j] += 1;
        }

        int front = n;
        vector<int> result;
        result.reserve(n);

        for (int q : queries) {
            int p = pos[q];
            int rank = 0;
            for (int j = p - 1; j > 0; j -= j & (-j))
                rank += bit[j];
            result.push_back(rank);
            for (int j = p; j <= sz; j += j & (-j))
                bit[j] -= 1;
            pos[q] = front;
            for (int j = front; j <= sz; j += j & (-j))
                bit[j] += 1;
            front--;
        }

        return result;
    }
};
